def find_survival_landmark(
    times,
    survival,
    threshold,
):
    for time, value in zip(times, survival):
        if value <= threshold:
            return time

    return None

relevant_functions.build_censoring_km:
def build_censoring_km(
    durations,
    events,
):

    observations = sorted(
        zip(
            durations,
            events,
        ),
        key=lambda x: x[0],
    )

    n = len(observations)

    times = []
    censor_counts = []
    at_risk = []

    i = 0
    removed = 0

    while i < n:

        time = observations[i][0]

        j = i
        censor_count = 0

        while (
            j < n
            and observations[j][0] == time
        ):

            if observations[j][1] == 0:
                censor_count += 1

            j += 1

        times.append(time)
        censor_counts.append(
            censor_count
        )
        at_risk.append(
            n - removed
        )

        removed += (
            j - i
        )

        i = j

    survival = []
    current = 1.0

    for censor_count, risk in zip(
        censor_counts,
        at_risk,
    ):

        if censor_count:
            current *= (
                1.0
                - censor_count / risk
            )

        survival.append(current)

    return (
        np.asarray(
            times,
            dtype=np.float64,
        ),
        np.asarray(
            survival,
            dtype=np.float64,
        ),
    )

