relevant_functions.survival:
def survival(
    self,
    X,
    time,
):

    eta = X @ self.beta_

    z = self.shape_ * (
        math.log(time) - eta
    )

    hazard = np.exp(
        np.clip(
            z,
            -700.0,
            700.0,
        )
    )

    return np.exp(-hazard)

relevant_functions.median_time:
def median_time(
    self,
    X,
):

    eta = X @ self.beta_

    return np.exp(
        eta
        + (
            math.log(
                math.log(2.0)
            )
            / self.shape_
        )
    )

relevant_functions.load_evaluation:
def load_evaluation(path):

    ids = []
    durations = []
    events = []

    with path.open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        reader = csv.DictReader(f)

        required = {
            "ID",
            "duration_seconds",
            "event",
        }

        missing = required - set(
            reader.fieldnames or []
        )

        if missing:
            raise RuntimeError(
                f"Evaluation split missing: "
                f"{sorted(missing)}"
            )

        for row in reader:

            ids.append(row["ID"])
            durations.append(
                float(
                    row["duration_seconds"]
                )
            )
            events.append(
                int(row["event"])
            )

    return (
        ids,
        np.asarray(
            durations,
            dtype=np.float64,
        ),
        np.asarray(
            events,
            dtype=np.int8,
        ),
    )

relevant_functions.load_predictions:
def load_predictions(path):

    ids = []

    durations = []
    events = []

    median_survival = []

    horizon_columns = []

    with path.open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        reader = csv.DictReader(f)

        fields = reader.fieldnames or []

        required = {
            "ID",
            "duration_seconds",
            "event",
            "predicted_median_survival_seconds",
        }

        missing = required - set(fields)

        if missing:
            raise RuntimeError(
                f"Prediction artifact missing: "
                f"{sorted(missing)}"
            )

        horizon_columns = [
            field
            for field in fields
            if field.startswith(
                "survival_probability_at_"
            )
        ]

        if not horizon_columns:
            raise RuntimeError(
                "No survival-probability horizon columns found."
            )

        for field in horizon_columns:
            print(
                f"Found prediction horizon: {field}"
            )

        for row in reader:

            ids.append(row["ID"])

            durations.append(
                float(
                    row["duration_seconds"]
                )
            )

            events.append(
                int(row["event"])
            )

            median_survival.append(
                float(
                    row[
                        "predicted_median_survival_seconds"
                    ]
                )
            )

    prediction_matrix = np.empty(
        (
            len(ids),
            len(horizon_columns),
        ),
        dtype=np.float64,
    )

    # Reload only the small prediction columns.
    with path.open(
        "r",
        encoding="utf-8",
        newline="",
    ) as f:

        reader = csv.DictReader(f)

        for i, row in enumerate(reader):

            for j, field in enumerate(
                horizon_columns
            ):

                prediction_matrix[
                    i,
                    j,
                ] = float(
                    row[field]
                )

    return (
        ids,
        np.asarray(
            durations,
            dtype=np.float64,
        ),
        np.asarray(
            events,
            dtype=np.int8,
        ),
        np.asarray(
            median_survival,
            dtype=np.float64,
        ),
        horizon_columns,
        prediction_matrix,
    )

